import { deleteProjectNote, type DeleteProjectNoteResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useProjectNoteRemove = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: { projectId: string }): Promise<DeleteProjectNoteResponse> =>
      deleteProjectNote({
        composable: '$fetch',
        path: { project_id: vars.projectId },
      }),
    onSuccess: async (_, { projectId }) => {
      showToastSuccess('Note removed successfully');
      await queryCache.invalidateQueries({ key: ['project', projectId], exact: true });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    projectNoteRemove: mutateAsync,
    isProjectNoteRemoveLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
