<template>
  <div data-testid="project-note-card">
    <EntityNote
      :note="note"
      :is-note-draft="isNoteDraft"
      :change-note-draft="changeNoteDraft"
      :update-note="onUpdate"
      :remove-note="onRemove"
      :is-update-loading="isProjectNoteUpsertLoading"
      :is-remove-loading="isProjectNoteRemoveLoading"
    />
  </div>
</template>

<script setup lang="ts">
import type { Note } from '~/client';
import { useProjectNoteUpsert } from '~/mutations/project/notes/upsert';
import { useProjectNoteRemove } from '~/mutations/project/notes/remove';

const props = defineProps<{
  projectId: string;
  note: Note | null;
  isNoteDraft: boolean;
  changeNoteDraft: () => void;
}>();

const { projectNoteUpsert, isProjectNoteUpsertLoading } = useProjectNoteUpsert();
const { projectNoteRemove, isProjectNoteRemoveLoading } = useProjectNoteRemove();

async function onUpdate(content: string) {
  await projectNoteUpsert({ projectId: props.projectId, content });
}

async function onRemove() {
  await projectNoteRemove({ projectId: props.projectId });
}
</script>
