<script setup lang="ts">
import { CircleCheckBigIcon, CircleXIcon, SignatureIcon } from 'lucide-vue-next';
import type { SignatureProjectStatistics } from '~/client';

interface Props {
  projectStartDate: string;
  statistics: SignatureProjectStatistics;
}

const props = defineProps<Props>();

const rawValidationRate = computed(() => {
  const total = props.statistics.raw.valid + props.statistics.raw.invalid;
  return total > 0 ? (props.statistics.valid.total / total) * 100 : 0.0;
});

const collectedValidationRate = computed(() => {
  const total = props.statistics.collected.valid + props.statistics.collected.invalid;
  return total > 0 ? (props.statistics.collected.valid / total) * 100 : 0.0;
});
