<template>
  <Card>
    <CardContent class="flex flex-col gap-4">
      <h3 class="text-xl font-semibold">Project progress</h3>
      <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div class="flex flex-col gap-2">
          <div class="flex items-center gap-2 font-bold">
            <SignatureIcon :class="cn('w-4 h-4 shrink-0')" />
            <span class="text-sm text-accent-foreground">
              Total Valid Collected
              <span class="text-muted-foreground">({{ progressPercentage.toFixed(2) }})%</span>
            </span>
            <span class="ml-auto">{{ Intl.NumberFormat('en-US').format(statistics.valid.total) }}</span>
          </div>
          <div class="flex items-center gap-2">
            <DotIcon :class="cn('stroke-[16px] w-4 h-4 shrink-0', validationStatisticsColors.validCollected.stroke)" />
            <span class="text-sm text-accent-foreground">
              Total Valid Turned In
              <span class="text-muted-foreground">({{ validCollectedPercentage.toFixed(2) }})%</span>
            </span>
            <span class="ml-auto">{{ Intl.NumberFormat('en-US').format(statistics.valid.collected) }}</span>
          </div>
          <!--          <div class="flex items-center gap-2">-->
          <!--            <DotIcon :class="cn('stroke-[16px] w-6 h-6', validationStatisticsColors.validNotCollected.stroke)" />-->
          <!--            <span class="text-sm text-accent-foreground">-->
          <!--              Valid Not Scanned-->
          <!--              <span class="text-muted-foreground">({{ validNotCollectedPercentage.toFixed(2) }})%</span>-->
          <!--            </span>-->
          <!--            <span class="ml-auto">{{ Intl.NumberFormat('en-US').format(statistics.valid.not_collected) }}</span>-->
          <!--          </div>-->
          <div class="flex items-center gap-2 font-bold">
            <DotIcon class="stroke-[16px] h-4 w-4 stroke-accent shrink-0" />
            <span class="text-sm text-accent-foreground">Goal</span>
            <span class="ml-auto">{{ Intl.NumberFormat('en-US').format(statistics.goal.signatures_goal) }}</span>
          </div>
        </div>
        <div class="flex flex-col items-center justify-center">
          <div class="font-bold text-4xl text-center">{{ progressPercentage.toFixed(2) }}%</div>
          <span v-if="etcDays >= 1" class="block text-center text-muted-foreground">
            ETC ~{{ etcDays.toFixed(0) }} days
          </span>
          <span class="block text-sm text-center text-muted-foreground">
            ({{ signaturesPerDay.toFixed(0) }} sig/day)
          </span>
        </div>
        <ComposedProgress class="col-span-1 sm:col-span-2" :segments="processedSegments" />
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { DotIcon, SignatureIcon } from 'lucide-vue-next';
import type { SignatureProjectStatistics } from '~/client';
import { validationStatisticsColors } from '~/constants/projects/validationStatistics';
import { cn } from '@/lib/utils';

interface Props {
  projectStartDate: string;
  statistics: SignatureProjectStatistics;
}

const props = defineProps<Props>();

const processedSegments = computed(() => {
  const baseSegments = [
    { value: props.statistics.valid.collected, color: validationStatisticsColors.validCollected.bg },
    { value: props.statistics.valid.not_collected, color: validationStatisticsColors.validNotCollected.bg },
  ];
  return normalizeSegments(baseSegments, props.statistics.goal.signatures_goal);
});

const validCollectedPercentage = computed(() => {
  return props.statistics.goal.signatures_goal > 0
    ? (props.statistics.valid.collected / props.statistics.goal.signatures_goal) * 100
    : 0.0;
});

const validNotCollectedPercentage = computed(() => {
  return props.statistics.goal.signatures_goal > 0
    ? (props.statistics.valid.not_collected / props.statistics.goal.signatures_goal) * 100
    : 0.0;
});

const progressPercentage = computed(() => {
  return props.statistics.goal.signatures_goal > 0
    ? (props.statistics.valid.total / props.statistics.goal.signatures_goal) * 100
    : 0.0;
});

const projectRunningDays = computed(() => {
  const startDate = new Date(props.projectStartDate);
  const currentDate = new Date();
  return Math.ceil((currentDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
});

const signaturesPerDay = computed(() => {
  return projectRunningDays.value > 0
    ? props.statistics.valid.total / projectRunningDays.value
    : props.statistics.valid.total;
});

const etcDays = computed(() => {
  return signaturesPerDay.value > 0
    ? (props.statistics.goal.signatures_goal - props.statistics.valid.total) / signaturesPerDay.value
    : 0.0;
});
</script>

<style scoped lang="scss"></style>
