import type { ProjectType } from '~/client';

const COMMON_CHECKLIST_ITEMS = [
  'Start and end dates locked in',
  'Voter database imported and verified',
  'Staffing goal set',
  'Target canvassers recruited',
  'Pay rates configured for Local and QRF',
  'Canvasser contract template configured',
  'Manager(s) assigned and onboarded',
  'Coaching config reviewed',
  'Training materials prepared and shared',
  'Project chat / communication channel created',
  'Project start announcement sent',
];

const SIGNATURE_CHECKLIST_ITEMS = [
  'Petition template uploaded and approved',
  'Signature verification rules set',
  'Region goals set',
];

const CANVASSING_CHECKLIST_ITEMS = [
  'Canvassing app project linked',
  'First app sync verified',
  'Canvassing questionnaire configured and approved',
];

export function getDefaultProjectChecklistTemplate(type: ProjectType): string[] {
  switch (type) {
    case 'signature':
      return [...COMMON_CHECKLIST_ITEMS, ...SIGNATURE_CHECKLIST_ITEMS];
    case 'canvassing':
      return [...COMMON_CHECKLIST_ITEMS, ...CANVASSING_CHECKLIST_ITEMS];
  }
}
