<template>
  <AppLoader v-if="isLoadingProject" subject="project" />
  <AppError v-else-if="error" title="Failed to load project" :error="error" />
  <AppEmpty v-else-if="!projectDetails" subject="project details" />
  <section v-else class="flex flex-col gap-4">
    <ProjectNavbar
      :project-id="projectDetails.id"
      :project-type="projectDetails.type"
      :project-status="projectDetails.status"
      :project-start-end-date="{ startDate: projectDetails.start_date, endDate: projectDetails.end_date }"
      :chat-id="projectDetails.chat_id"
    >
      <DropdownMenu v-if="canImportInteractions" :modal="false">
        <DropdownMenuTrigger>
          <Button variant="ghost" size="icon" class="rounded-full" data-testid="project-details-actions-menu-btn">
            <EllipsisVerticalIcon />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem data-testid="project-details-import-csv-btn" @click="importCsvOpen = true">
            <Upload />
            Import CSV
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </ProjectNavbar>
    <Alert v-if="canvasserContract && canvasserContractAlert && isCanvasser" variant="info">
      <InfoIcon />
      <AlertTitle>{{ canvasserContractAlert.title }}</AlertTitle>
      <AlertDescription class="mb-3">{{ canvasserContractAlert.description }}</AlertDescription>
      <NuxtLink :to="{ name: 'contracts-id', params: { id: canvasserContract.id } }" class="inline-block">
        <Button size="sm">{{ canvasserContractAlert.actionLabel }}</Button>
      </NuxtLink>
    </Alert>
    <div class="gap-4 md:gap-5 grid grid-cols-3">
      <div class="flex flex-col gap-4 col-span-3 xl:col-span-2 flex-auto order-2 xl:order-1 md:gap-5">
        <ProjectDailyReviewCard
          v-if="dailyReviewProjectId && pendingReviewData"
          :project-id="dailyReviewProjectId"
          :pending-data="pendingReviewData"
        />
        <Card>
          <CardHeader>
            <CardTitle class="text-2xl font-semibold">Description</CardTitle>
          </CardHeader>
          <CardContent class="text-accent-foreground">
            <AppMarkdown :markdown="$marked(projectDetails.description)" />
          </CardContent>
        </Card>
        <template v-if="isManagerOrAdminData(projectDetails)">
          <ProjectChecklistCard
            :project-id="projectDetails.id.toString()"
            :project-type="projectDetails.type"
            :items="projectDetails.checklist ?? null"
          />
          <ProjectNoteCard
            :project-id="projectDetails.id.toString()"
            :note="projectDetails.note ?? null"
            :is-note-draft="isNoteDraft"
            :change-note-draft="changeNoteDraft"
          />
        </template>
        <template v-if="projectDetails.type === 'signature'">
          <ProjectValidationStatistics
            v-if="projectDetails.statistics && isSignatureProjectStatistics(projectDetails.statistics)"
            :project-start-date="projectDetails.start_date"
            :statistics="projectDetails.statistics"
          />
          <ProjectProgress
            v-if="projectDetails.statistics && isSignatureProjectStatistics(projectDetails.statistics)"
            :project-start-date="projectDetails.start_date"
            :statistics="projectDetails.statistics"
          />
        </template>
      </div>
      <div
        class="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-1 gap-4 col-span-3 xl:col-span-1 order-1 xl:order-2 md:gap-5 h-fit"
      >
        <ProjectInfoCard
          v-for="card in projectInfoCards"
          :key="card.title"
          :data="card"
          :class="[card.to ? 'cursor-pointer' : '']"
          @click="navigateToOnClick(card.to)"
        >
          <div class="flex items-center gap-2 justify-between min-w-0">
            <Badge v-if="card.isBadgedData" :class="cn('text-sm', card.isBadgedData.class)">
              {{ card.value }}
            </Badge>
            <p v-else class="text-xl max-sm:text-base md:max-xl:text-base font-semibold line-clamp-1 min-w-0 break-all">
              {{ card.value }}
            </p>
            <Badge
              v-if="card.additionalValue?.isBadged"
              :class="cn('text-sm', card.additionalValue.class)"
              :variant="card.additionalValue.variant"
            >
              {{ card.additionalValue.value }}
            </Badge>
            <p v-else-if="card.additionalValue" :class="cn('text-sm')">
              {{ card.additionalValue.value }}
            </p>
          </div>
          <Progress v-if="'progressValue' in card" v-model="card.progressValue" class="bg-accent h-2.5" />
        </ProjectInfoCard>
      </div>
    </div>
    <UploadModal
      v-if="projectDetails"
      v-model="importCsvOpen"
      :project-id="projectDetails.id.toString()"
      @uploaded="onCsvUploaded"
    />
  </section>
</template>

<script setup lang="ts">
import {
  Calendar,
  Contact,
  Clipboard,
  Database,
  UsersRound,
  BriefcaseBusiness,
  Smartphone,
  CalendarSync,
  InfoIcon,
  Upload,
  EllipsisVerticalIcon,
} from 'lucide-vue-next';
import type {
  GetProjectDetailsResponse,
  ProjectDetailsForAdmin,
  ProjectDetailsForCanvasser,
  ProjectDetailsForManager,
  SignatureProjectStatistics,
  CanvassingProjectDetailsStatistics,
} from '~/client';
import { cn } from '@/lib/utils';
import {
  getProjectStaffingStatus,
  getVoterDatabaseStatus,
  getBallotTemplateStateVariant,
  getProjectTypeLabel,
  getProjectCanvassingAppLabel,
  getCanvassingAppSyncStatusVariant,
  getCanvasserContractAlert,
} from '~/constants/projects';
import type { TypedNuxtLink } from '#build/typed-router/typed-router';

definePageMeta({
  backGroup: 'project-details',
  backLabel: 'project',
});

const { projectDetails, isLoading: isLoadingProject, error } = useProjectDetails();
const { isCanvasser } = useUserRole();

const importCsvOpen = ref(false);

const canImportInteractions = computed(
  () =>
    !!projectDetails.value && projectDetails.value.type === 'canvassing' && isManagerOrAdminData(projectDetails.value)
);

async function onCsvUploaded(importId: string) {
  await navigateTo({
    name: 'canvassing-interaction-imports-importId',
    params: { importId },
  });
}

const isNoteDraft = ref<boolean>(false);
function changeNoteDraft() {
  isNoteDraft.value = !isNoteDraft.value;
}
const { $marked } = useNuxtApp();

const canvasserContract = computed(() => {
  const details = projectDetails.value;
  if (!details || !isCanvasserData(details)) return null;
  const { contract } = details;
  if (!contract || contract.status !== 'pending' || contract.signed_by_canvasser) return null;
  return contract;
});

const canvasserContractAlert = computed(() =>
  canvasserContract.value ? getCanvasserContractAlert(canvasserContract.value.signed_by_admin) : null
);

function isCanvasserData(data: GetProjectDetailsResponse): data is ProjectDetailsForCanvasser {
  return 'contract' in data;
}

useHead({
  title: computed(() => projectDetails.value?.name ?? ''),
});

const { timezone } = useUserRole();

// Daily review pending counts — only fetched for canvassing projects viewed by an
// admin/manager (undefined id keeps the query disabled otherwise).
const dailyReviewProjectId = computed(() =>
  projectDetails.value && projectDetails.value.type === 'canvassing' && isManagerOrAdminData(projectDetails.value)
    ? projectDetails.value.id.toString()
    : undefined
);
const { data: pendingReviewData } = useProjectDailyReviewPendingDatesQuery(dailyReviewProjectId);

//TODO: Refactor projectInfoCards
const projectInfoCards = computed<ProjectInfoCardData[]>(() => {
  if (!projectDetails.value) return [];

  return [
    {
      title: 'Type',
      value: getProjectTypeLabel(projectDetails.value.type),
      icon: BriefcaseBusiness,
      isBadgedData: { class: '' },
    },
    {
      title: 'Duration',
      value:
        formatDateToFormat(projectDetails.value.start_date, 'MM/dd/yyyy') +
        ' - ' +
        formatDateToFormat(projectDetails.value.end_date, 'MM/dd/yyyy'),
      icon: Calendar,
    },
    {
      title: 'Client',
      value: projectDetails.value.client,
      icon: Contact,
    },
    ...(projectDetails.value.type === 'signature'
      ? [
          {
            title: 'Petition Template',
            value: projectDetails.value.ballot_template?.name || 'Not set',
            icon: Clipboard,
            isBadgedData: !projectDetails.value.ballot_template?.name
              ? {
                  class: 'bg-red-200 text-red-800',
                }
              : undefined,
            to: { name: 'projects-id-ballot-template', params: { id: projectDetails.value.id.toString() } },
            ...(projectDetails.value.ballot_template?.state
              ? {
                  additionalValue: {
                    isBadged: true,
                    value: projectDetails.value.ballot_template?.state,
                    variant: getBallotTemplateStateVariant(projectDetails.value.ballot_template?.state),
                  },
                }
              : {}),
          },
        ]
      : []),
    {
      title: 'Voter Database',
      value:
        projectDetails.value.voter_database?.status === null
          ? 'Not set'
          : projectDetails.value.voter_database.status === 'imported'
            ? projectDetails.value.voter_database.name
            : projectDetails.value.voter_database?.status,
      icon: Database,
      to: { name: 'projects-id-voter-database', params: { id: projectDetails.value.id.toString() } },
      isBadgedData:
        !projectDetails.value.voter_database?.name || projectDetails.value.voter_database?.status !== 'imported'
          ? {
              class: projectDetails.value.voter_database?.status
                ? getVoterDatabaseStatus(projectDetails.value.voter_database?.status).color
                : 'bg-red-200 text-red-800',
            }
          : undefined,
    },
    ...(projectDetails.value.type === 'canvassing' && isManagerOrAdminData(projectDetails.value)
      ? [
          {
            title: 'Canvassing App Project',
            value: projectDetails.value.canvassing_app_project
              ? projectDetails.value.canvassing_app_project
              : 'Not set',
            icon: Smartphone,
            isBadgedData: !projectDetails.value.canvassing_app_project
              ? {
                  class: 'bg-red-200 text-red-800',
                }
              : undefined,
            additionalValue: projectDetails.value.canvassing_app_type
              ? {
                  isBadged: true,
                  value: getProjectCanvassingAppLabel(projectDetails.value.canvassing_app_type),
                }
              : undefined,
          },
        ]
      : []),
    ...(projectDetails.value.type === 'canvassing' && isManagerOrAdminData(projectDetails.value)
      ? [
          {
            title: 'Canvassing App Sync',
            value: projectDetails.value.canvassing_app_last_sync
              ? formatDateTzToFormat(
                  projectDetails.value.canvassing_app_last_sync,
                  'MM/dd/yyyy, hh:mm aaa',
                  timezone.value
                )
              : 'Not synced',
            isBadgedData: !projectDetails.value.canvassing_app_last_sync
              ? {
                  class: 'bg-red-200 text-red-800',
                }
              : undefined,
            icon: CalendarSync,
            ...(projectDetails.value.canvassing_app_sync_status && {
              additionalValue: {
                isBadged: true,
                value: projectDetails.value.canvassing_app_sync_status,
                variant: getCanvassingAppSyncStatusVariant(projectDetails.value.canvassing_app_sync_status),
              },
            }),
          },
        ]
      : []),
    ...(isManagerOrAdminData(projectDetails.value)
      ? [
          {
            title: 'Staffing',
            icon: UsersRound,
            value: projectDetails.value.total_canvassers + ' / ' + projectDetails.value.staffing_goal,
            additionalValue: {
              isBadged: true,
              value: getProjectStaffingStatus(projectDetails.value.staffing_status).label,
              class: getProjectStaffingStatus(projectDetails.value.staffing_status).color,
            },
          },
        ]
      : []),
  ];
});

function isManagerOrAdminData(
  data: GetProjectDetailsResponse
): data is ProjectDetailsForAdmin | ProjectDetailsForManager {
  return 'staffing_goal' in data;
}

async function navigateToOnClick(to: TypedNuxtLink['to'] | undefined) {
  if (to) {
    await navigateTo(to);
  }
}

function isSignatureProjectStatistics(
  statistics: CanvassingProjectDetailsStatistics | SignatureProjectStatistics
): statistics is SignatureProjectStatistics {
  return 'valid_submitted_signatures' in statistics;
}
</script>

<style scoped lang="scss"></style>
