import { addChecklistItem, type AddChecklistItemResponse, type GetProjectDetailsResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useProjectChecklistAdd = defineMutation(() => {
  const queryCache = useQueryCache();

  const projectKey = (projectId: string) => ['project', projectId];

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: { projectId: string; content: string }): Promise<AddChecklistItemResponse> =>
      addChecklistItem({
        composable: '$fetch',
        path: { project_id: vars.projectId },
        body: { content: vars.content },
      }),
    onSuccess: (response, { projectId }) => {
      showToastSuccess('Checklist item added successfully');
      queryCache.setQueryData(projectKey(projectId), (oldData?: GetProjectDetailsResponse) => {
        if (!oldData || !('checklist' in oldData)) return oldData;
        return {
          ...oldData,
          checklist: [...(oldData.checklist ?? []), response.item],
        };
      });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    projectChecklistAdd: mutateAsync,
    isProjectChecklistAddLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
