import {
  updateChecklistItem,
  type ChecklistItem,
  type GetProjectDetailsResponse,
  type UpdateChecklistItemResponse,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useProjectChecklistUpdate = defineMutation(() => {
  const queryCache = useQueryCache();

  const projectKey = (projectId: string) => ['project', projectId];

  const patchItem = (
    data: GetProjectDetailsResponse | undefined,
    itemId: string,
    patch: Partial<ChecklistItem>
  ): GetProjectDetailsResponse | undefined => {
    if (!data || !('checklist' in data) || !data.checklist) return data;
    return {
      ...data,
      checklist: data.checklist.map((item) => (item.id === itemId ? { ...item, ...patch } : item)),
    };
  };

  const { mutateAsync, asyncStatus } = useMutation({
    onMutate: (vars: { projectId: string; itemId: string; content?: string; done?: boolean }) => {
      const key = projectKey(vars.projectId);
      queryCache.cancelQueries({ key, exact: true });
      const previousData = queryCache.getQueryData(key) as GetProjectDetailsResponse | undefined;
      queryCache.setQueryData(key, (oldData?: GetProjectDetailsResponse) =>
        patchItem(oldData, vars.itemId, {
          ...(vars.content !== undefined ? { content: vars.content } : {}),
          ...(vars.done !== undefined ? { done: vars.done } : {}),
        })
      );
      return { previousData };
    },
    mutation: (vars: {
      projectId: string;
      itemId: string;
      content?: string;
      done?: boolean;
    }): Promise<UpdateChecklistItemResponse> =>
      updateChecklistItem({
        composable: '$fetch',
        path: { project_id: vars.projectId, item_id: vars.itemId },
        body: { content: vars.content, done: vars.done },
      }),
    onSuccess: (response, vars) => {
      showToastSuccess('Checklist item updated successfully');
      queryCache.setQueryData(projectKey(vars.projectId), (oldData?: GetProjectDetailsResponse) =>
        patchItem(oldData, vars.itemId, response.item)
      );
    },
    onError(error, vars, context) {
      showToastError(error);
      if (context.previousData !== undefined) {
        queryCache.setQueryData(projectKey(vars.projectId), context.previousData);
      }
    },
  });

  return {
    projectChecklistUpdate: mutateAsync,
    isProjectChecklistUpdateLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
