import { upsertProjectNote, type UpsertProjectNoteResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useProjectNoteUpsert = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: { projectId: string; content: string }): Promise<UpsertProjectNoteResponse> =>
      upsertProjectNote({
        composable: '$fetch',
        path: { project_id: vars.projectId },
        body: { content: vars.content },
      }),
    onSuccess: async (_, { projectId }) => {
      showToastSuccess('Note saved successfully');
      await queryCache.invalidateQueries({ key: ['project', projectId], exact: true });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    projectNoteUpsert: mutateAsync,
    isProjectNoteUpsertLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
