import { deleteChecklistItem, type DeleteChecklistItemResponse, type GetProjectDetailsResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useProjectChecklistRemove = defineMutation(() => {
  const queryCache = useQueryCache();

  const projectKey = (projectId: string) => ['project', projectId];

  const { mutateAsync, asyncStatus } = useMutation({
    onMutate: (vars: { projectId: string; itemId: string }) => {
      const key = projectKey(vars.projectId);
      queryCache.cancelQueries({ key, exact: true });
      const previousData = queryCache.getQueryData(key) as GetProjectDetailsResponse | undefined;
      queryCache.setQueryData(key, (oldData?: GetProjectDetailsResponse) => {
        if (!oldData || !('checklist' in oldData) || !oldData.checklist) return oldData;
        return {
          ...oldData,
          checklist: oldData.checklist.filter((item) => item.id !== vars.itemId),
        };
      });
      return { previousData };
    },
    mutation: (vars: { projectId: string; itemId: string }): Promise<DeleteChecklistItemResponse> =>
      deleteChecklistItem({
        composable: '$fetch',
        path: { project_id: vars.projectId, item_id: vars.itemId },
      }),
    onSuccess: () => {
      showToastSuccess('Checklist item removed successfully');
    },
    onError(error, vars, context) {
      showToastError(error);
      if (context.previousData !== undefined) {
        queryCache.setQueryData(projectKey(vars.projectId), context.previousData);
      }
    },
  });

  return {
    projectChecklistRemove: mutateAsync,
    isProjectChecklistRemoveLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
