import { addChecklistItem, type ChecklistItem, type GetProjectDetailsResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useProjectChecklistApplyTemplate = defineMutation(() => {
  const queryCache = useQueryCache();
  const projectKey = (projectId: string) => ['project', projectId];

  const appendToCache = (projectId: string, item: ChecklistItem) => {
    queryCache.setQueryData(projectKey(projectId), (oldData?: GetProjectDetailsResponse) => {
      if (!oldData || !('checklist' in oldData)) return oldData;
      return {
        ...oldData,
        checklist: [...(oldData.checklist ?? []), item],
      };
    });
  };

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: async (vars: { projectId: string; contents: string[] }): Promise<ChecklistItem[]> => {
      const items: ChecklistItem[] = [];
      for (const content of vars.contents) {
        const response = await addChecklistItem({
          composable: '$fetch',
          path: { project_id: vars.projectId },
          body: { content },
        });
        appendToCache(vars.projectId, response.item);
        items.push(response.item);
      }
      return items;
    },
    onSuccess: () => {
      showToastSuccess('Default checklist applied successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    projectChecklistApplyTemplate: mutateAsync,
    isProjectChecklistApplyTemplateLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
