<template>
  <Card data-testid="project-checklist-card">
    <CardHeader class="flex flex-row items-center justify-between space-y-0">
      <CardTitle class="text-2xl font-semibold">Checklist</CardTitle>
      <span v-if="totalCount > 0" class="text-sm text-muted-foreground" data-testid="project-checklist-summary">
        {{ doneCount }} of {{ totalCount }} complete
      </span>
    </CardHeader>
    <CardContent>
      <div
        v-if="totalCount === 0"
        class="flex flex-col items-center justify-center gap-3 rounded-lg border border-dashed border-muted-foreground/30 bg-muted/40 px-6 py-8 mb-3"
      >
        <div class="rounded-full bg-background p-3 ring-1 ring-muted-foreground/15">
          <ListChecks class="h-6 w-6 text-muted-foreground" />
        </div>
        <div class="text-center max-w-sm">
          <p class="text-sm font-medium" data-testid="project-checklist-empty">No checklist items yet</p>
          <p class="text-xs text-muted-foreground mt-1">
            Start with a recommended {{ getProjectTypeLabel(projectType).toLowerCase() }} project checklist, or add
            items one at a time.
          </p>
        </div>
        <div class="flex flex-col items-center gap-2">
          <Button
            type="button"
            size="sm"
            :prepend-icon="Sparkles"
            :loading="isProjectChecklistApplyTemplateLoading"
            :disabled="isProjectChecklistApplyTemplateLoading"
            data-testid="project-checklist-apply-template"
            @click="applyTemplate()"
          >
            Apply default checklist
          </Button>
          <button
            type="button"
            class="text-xs text-muted-foreground hover:text-foreground underline-offset-2 hover:underline focus-visible:outline-none focus-visible:underline"
            data-testid="project-checklist-add-manually"
            @click="focusAddInput()"
          >
            Or add your first item manually below
          </button>
        </div>
      </div>
      <ul class="divide-y">
        <li
          v-for="item in sortedItems"
          :key="item.id"
          class="flex items-center gap-2 py-2 group"
          :data-testid="`project-checklist-item-${item.id}`"
        >
          <Checkbox
            class="shrink-0"
            :model-value="item.done"
            :disabled="togglingItemId === item.id || editingItemId === item.id"
            :data-testid="`project-checklist-toggle-${item.id}`"
            @update:model-value="toggleDone(item)"
          />
          <Input
            v-if="editingItemId === item.id"
            :ref="setEditInputRef"
            v-model="editingDraft"
            class="flex-1 min-w-0 h-8"
            :disabled="editingBusy"
            :data-testid="`project-checklist-edit-input-${item.id}`"
            @keydown.enter.prevent="commitEdit(item)"
            @keydown.esc.prevent="cancelEdit()"
            @blur="commitEdit(item)"
          />
          <span
            v-else
            class="flex-1 min-w-0 break-words cursor-text"
            :class="item.done ? 'line-through text-muted-foreground' : ''"
            @click="startEdit(item)"
          >
            {{ item.content }}
          </span>
          <!-- Edit affordance: hover-revealed on desktop; on touch the item is edited by tapping the text directly. -->
          <button
            v-if="editingItemId !== item.id"
            type="button"
            class="shrink-0 invisible group-hover:visible text-muted-foreground hover:text-foreground"
            :data-testid="`project-checklist-edit-${item.id}`"
            :aria-label="`Edit item ${item.content}`"
            @click="startEdit(item)"
          >
            <Pencil class="h-4 w-4" />
          </button>
          <!--
            Delete affordance is always rendered so it stays reachable while editing on touch.
            Reveal is mutually exclusive by device, driven by edit state (`editingItemId`) rather
            than :focus-within — the latter also fires for checkbox / edit-button focus, which
            would spuriously hide delete on hover devices right after toggling an item.
            - hover devices: shown on hover. While editing it's `display:none`, so it takes NO
              reserved space and the input fills the row — matching the pre-existing desktop
              behavior where nothing extra showed during edit.
            - no-hover (touch) devices: hidden until the item is being edited (tap the text to
              edit), then shown to the right of the input.
          -->
          <ConfirmationDialog
            v-if="item.done"
            title="Delete completed item?"
            description="This will permanently remove the item from the project checklist."
            confirm-btn-variant="destructive"
            confirm-btn-text="Delete"
            :is-confirm-loading="deletingItemId === item.id"
            @confirm="deleteItem(item)"
          >
            <button
              type="button"
              :class="[
                'shrink-0 text-muted-foreground hover:text-destructive',
                editingItemId === item.id
                  ? '[@media(hover:none)]:visible [@media(hover:hover)]:hidden'
                  : 'invisible group-hover:visible',
              ]"
              :data-testid="`project-checklist-delete-${item.id}`"
              :aria-label="`Delete item ${item.content}`"
              @pointerdown.prevent
            >
              <Trash2Icon class="h-4 w-4" />
            </button>
          </ConfirmationDialog>
          <button
            v-else
            type="button"
            :class="[
              'shrink-0 text-muted-foreground hover:text-destructive',
              editingItemId === item.id
                ? '[@media(hover:none)]:visible [@media(hover:hover)]:hidden'
                : 'invisible group-hover:visible',
            ]"
            :data-testid="`project-checklist-delete-${item.id}`"
            :aria-label="`Delete item ${item.content}`"
            :disabled="deletingItemId === item.id"
            @pointerdown.prevent
            @click="deleteItem(item)"
          >
            <Trash2Icon class="h-4 w-4" />
          </button>
        </li>
      </ul>
      <div class="flex items-center gap-2 pt-2">
        <Plus class="h-4 w-4 text-muted-foreground" />
        <Input
          ref="addInputRef"
          v-model="newItemContent"
          placeholder="Add item"
          class="flex-1 h-8"
          :disabled="isProjectChecklistAddLoading"
          data-testid="project-checklist-add-input"
          @keydown.enter.prevent="addItem()"
        />
        <Button
          type="button"
          size="sm"
          variant="secondary"
          class="h-8"
          :disabled="!canAdd"
          data-testid="project-checklist-add-button"
          @click="addItem()"
        >
          Add
        </Button>
      </div>
      <p v-if="lastUpdated" class="text-xs text-muted-foreground mt-3" data-testid="project-checklist-footer">
        Last updated {{ formatDateToFormat(lastUpdated.updated_at, 'MM/dd/yyyy, hh:mm aaa') }}
        <span v-if="lastUpdated.updated_by"> by <InlineEntityUser :user-id="lastUpdated.updated_by" /> </span>
      </p>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { computed, nextTick, ref } from 'vue';
import type { ChecklistItem, ProjectType } from '~/client';
import { getDefaultProjectChecklistTemplate } from '~/constants/projects/projectChecklistTemplate';
import { getProjectTypeLabel } from '~/constants/projects/projectTypesConfig';
import { Pencil, Trash2Icon, Plus, ListChecks, Sparkles } from 'lucide-vue-next';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import ConfirmationDialog from '@/components/common/ConfirmationDialog.vue';
import InlineEntityUser from '@/components/common/labeled-entity/InlineEntityUser.vue';
import { formatDateToFormat } from '@/utils/formatDateToFormat';
import { useProjectChecklistUpdate } from '~/mutations/project/checklist/update';
import { useProjectChecklistRemove } from '~/mutations/project/checklist/remove';
import { useProjectChecklistAdd } from '~/mutations/project/checklist/add';
import { useProjectChecklistApplyTemplate } from '~/mutations/project/checklist/applyTemplate';

const props = defineProps<{
  projectId: string;
  projectType: ProjectType;
  items: ChecklistItem[] | null;
}>();

const sortedItems = computed<ChecklistItem[]>(() => {
  const copy = [...(props.items ?? [])];
  copy.sort((a, b) => {
    const cmp = a.created_at.localeCompare(b.created_at);
    return cmp !== 0 ? cmp : a.id.localeCompare(b.id);
  });
  return copy;
});

const totalCount = computed(() => sortedItems.value.length);
const doneCount = computed(() => sortedItems.value.filter((i) => i.done).length);

const lastUpdated = computed<ChecklistItem | null>(() => {
  if (sortedItems.value.length === 0) return null;
  return sortedItems.value.reduce<ChecklistItem | null>((acc, i) => {
    if (!acc) return i;
    return i.updated_at > acc.updated_at ? i : acc;
  }, null);
});

const { projectChecklistUpdate } = useProjectChecklistUpdate();

const togglingItemId = ref<string | null>(null);

async function toggleDone(item: ChecklistItem) {
  if (togglingItemId.value) return;
  togglingItemId.value = item.id;
  try {
    await projectChecklistUpdate({
      projectId: props.projectId,
      itemId: item.id,
      done: !item.done,
    });
  } finally {
    togglingItemId.value = null;
  }
}

const editingItemId = ref<string | null>(null);
const editingDraft = ref('');
const editingBusy = ref(false);

// The edit input is inserted dynamically, so the `autofocus` attribute is unreliable
// (notably on touch/mobile WebKit). Focus it explicitly so a single tap opens the editor,
// pops the keyboard, and reveals the delete button via :focus-within.
const editInputEl = ref<HTMLInputElement | null>(null);
function setEditInputRef(el: unknown) {
  if (!el) {
    editInputEl.value = null;
    return;
  }
  editInputEl.value =
    typeof el === 'object' && '$el' in el ? ((el as { $el: HTMLInputElement }).$el ?? null) : (el as HTMLInputElement);
}

function startEdit(item: ChecklistItem) {
  if (editingItemId.value) return;
  editingItemId.value = item.id;
  editingDraft.value = item.content;
  void nextTick(() => editInputEl.value?.focus());
}

function cancelEdit() {
  editingItemId.value = null;
  editingDraft.value = '';
}

async function commitEdit(item: ChecklistItem) {
  const next = editingDraft.value.trim();
  if (!next || next === item.content) {
    cancelEdit();
    return;
  }
  editingBusy.value = true;
  try {
    await projectChecklistUpdate({
      projectId: props.projectId,
      itemId: item.id,
      content: next,
    });
    cancelEdit();
  } finally {
    editingBusy.value = false;
  }
}

const { projectChecklistRemove } = useProjectChecklistRemove();

const deletingItemId = ref<string | null>(null);

async function deleteItem(item: ChecklistItem) {
  if (deletingItemId.value) return;
  deletingItemId.value = item.id;
  try {
    await projectChecklistRemove({ projectId: props.projectId, itemId: item.id });
  } finally {
    deletingItemId.value = null;
  }
}

const { projectChecklistAdd, isProjectChecklistAddLoading } = useProjectChecklistAdd();

const newItemContent = ref('');
const addInputRef = ref<{ $el?: HTMLInputElement } | HTMLInputElement | null>(null);

function focusAddInput() {
  const r = addInputRef.value;
  const el = r && typeof r === 'object' && '$el' in r ? r.$el : (r as HTMLInputElement | null);
  el?.focus();
}

const canAdd = computed(() => !!newItemContent.value.trim() && !isProjectChecklistAddLoading.value);

async function addItem() {
  if (!canAdd.value) return;
  const next = newItemContent.value.trim();
  try {
    await projectChecklistAdd({ projectId: props.projectId, content: next });
    newItemContent.value = '';
  } catch {
    // toast already shown by the mutation; keep the input contents so user can retry
  }
}

const { projectChecklistApplyTemplate, isProjectChecklistApplyTemplateLoading } = useProjectChecklistApplyTemplate();

async function applyTemplate() {
  if (isProjectChecklistApplyTemplateLoading.value) return;
  const contents = getDefaultProjectChecklistTemplate(props.projectType);
  try {
    await projectChecklistApplyTemplate({ projectId: props.projectId, contents });
  } catch {
    // toast already shown by the mutation; partial items (if any) are already in the cache
  }
}
</script>
