import type { CanvassingApplicationSyncStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

export const canvassingAppSyncStatusBadgeVariant: Record<CanvassingApplicationSyncStatus, BadgeVariants> = {
  pending: 'default',
  success: 'success',
  failed: 'destructive',
};

export function getCanvassingAppSyncStatusVariant(status: CanvassingApplicationSyncStatus): BadgeVariants {
  return canvassingAppSyncStatusBadgeVariant[status] ?? 'default';
}
