type CanvasserContractAlertState = 'awaiting_canvasser' | 'awaiting_admin';

export interface CanvasserContractAlertEntry {
  title: string;
  description: string;
  actionLabel: string;
}

export const canvasserContractAlertConfig: Record<CanvasserContractAlertState, CanvasserContractAlertEntry> = {
  awaiting_canvasser: {
    title: 'Contract awaiting your signature',
    description: 'Sign your contract to get started on this project.',
    actionLabel: 'Sign Contract',
  },
  awaiting_admin: {
    title: 'Contract awaiting admin signature',
    description: "You'll be able to sign your contract once the admin has signed it.",
    actionLabel: 'See Details',
  },
};

export function getCanvasserContractAlert(signedByAdmin: boolean): CanvasserContractAlertEntry {
  return canvasserContractAlertConfig[signedByAdmin ? 'awaiting_canvasser' : 'awaiting_admin'];
}
